462: /****************************************************************************
463:  * Name: sc2336_write_reg
464:  *
465:  * Description:
466:  *   Write one 8-bit value to a 16-bit register address over SCCB.
467:  *
468:  ****************************************************************************/
469: 
470: static int sc2336_write_reg(FAR struct sc2336_dev_s *priv, uint16_t reg,
471:                             uint8_t val)
472: {
473:   struct i2c_msg_s msg;
474:   uint8_t buf[SC2336_REGADDR_LEN + 1];
475:   int ret;
476: 
477:   buf[0] = (uint8_t)(reg >> 8);
478:   buf[1] = (uint8_t)(reg & 0xff);
479:   buf[2] = val;
480: 
481:   msg.frequency = SC2336_I2C_FREQUENCY;
482:   msg.addr      = priv->addr;
483:   msg.flags     = 0;
484:   msg.buffer    = buf;
485:   msg.length    = sizeof(buf);
486: 
487:   ret = I2C_TRANSFER(priv->i2c, &msg, 1);
488: 
489: #ifdef CONFIG_SC2336_DEBUG
490:   _info("SC2336: W %04x = %02x ret=%d\n", reg, val, ret);
491: #endif
492: 
493:   return ret < 0 ? ret : OK;
494: }
495: 
496: /****************************************************************************
497:  * Name: sc2336_read_reg
498:  *
499:  * Description:
500:  *   Read one 8-bit value from a 16-bit register address over SCCB.  SCCB has
501:  *   no repeated-START support, so the transfer is done as two separate I2C
502:  *   messages: address write, then data read.
503:  *
504:  ****************************************************************************/
505: 
506: static int sc2336_read_reg(FAR struct sc2336_dev_s *priv, uint16_t reg,
507:                            FAR uint8_t *val)
508: {
509:   struct i2c_msg_s msg[2];
510:   uint8_t addr[SC2336_REGADDR_LEN];
511:   int ret;
512: 
513:   addr[0] = (uint8_t)(reg >> 8);
514:   addr[1] = (uint8_t)(reg & 0xff);
515: 
516:   msg[0].frequency = SC2336_I2C_FREQUENCY;
517:   msg[0].addr      = priv->addr;
518:   msg[0].flags     = 0;
519:   msg[0].buffer    = addr;
520:   msg[0].length    = sizeof(addr);
521: 
522:   msg[1].frequency = SC2336_I2C_FREQUENCY;
523:   msg[1].addr      = priv->addr;
524:   msg[1].flags     = I2C_M_READ;
525:   msg[1].buffer    = val;
526:   msg[1].length    = 1;
527: 
528:   ret = I2C_TRANSFER(priv->i2c, msg, 2);
529: 
530: #ifdef CONFIG_SC2336_DEBUG
531:   _info("SC2336: R %04x -> %02x ret=%d\n", reg, *val, ret);
532: #endif
533: 
534:   return ret < 0 ? ret : OK;
535: }
536: 
537: /****************************************************************************
538:  * Name: sc2336_write_table
539:  *
540:  * Description:
541:  *   Apply a vendor register table in order.  0xffff terminates the table and
542:  *   0xfffe requests a delay of val milliseconds.
543:  *
544:  ****************************************************************************/
545: 
546: static int sc2336_write_table(FAR struct sc2336_dev_s *priv,
547:                               FAR const struct sc2336_reg_s *table)
548: {
549:   FAR const struct sc2336_reg_s *p;
550:   int ret;
551: 
552:   for (p = table; p->reg != SC2336_REG_END; p++)
553:     {
554:       if (p->reg == SC2336_REG_DELAY)
555:         {
556:           nxsig_usleep((useconds_t)p->val * 1000);
557:           continue;
558:         }
559: 
560:       ret = sc2336_write_reg(priv, p->reg, p->val);
561:       if (ret < 0)
562:         {
563:           _err("ERROR: SC2336: write %04x failed: %d\n", p->reg, ret);
564:           return ret;
565:         }
566:     }
567: 
568:   return OK;
569: }
