571: /****************************************************************************
572:  * Name: sc2336_set_exposure
573:  *
574:  * Description:
575:  *   Program the integration time.  The SC2336 spreads the 16-bit exposure
576:  *   over three registers: 0x3e00[3:0] = exposure[15:12],
577:  *   0x3e01 = exposure[11:4], 0x3e02[7:4] = exposure[3:0].
578:  *
579:  ****************************************************************************/
580: 
581: static int sc2336_set_exposure(FAR struct sc2336_dev_s *priv,
582:                                uint32_t exposure)
583: {
584:   uint8_t val;
585:   int ret;
586: 
587:   if (exposure < SC2336_EXPOSURE_MIN)
588:     {
589:       exposure = SC2336_EXPOSURE_MIN;
590:     }
591:   else if (exposure > SC2336_EXPOSURE_MAX)
592:     {
593:       exposure = SC2336_EXPOSURE_MAX;
594:     }
595: 
596:   /* 0x3e02 keeps whatever is in bits [3:0] (the vendor driver masks only the
597:    * upper nibble), so it is read back before the new value is written.
598:    */
599: 
600:   ret = sc2336_read_reg(priv, SC2336_REG_SHUTTER_L, &val);
601:   if (ret < 0)
602:     {
603:       return ret;
604:     }
605: 
606:   val = (val & 0x0f) | ((uint8_t)(exposure & 0x0f) << 4);
607: 
608:   ret = sc2336_write_reg(priv, SC2336_REG_SHUTTER_H,
609:                          (uint8_t)(exposure >> 12) & 0x0f);
610:   if (ret < 0)
611:     {
612:       return ret;
613:     }
614: 
615:   ret = sc2336_write_reg(priv, SC2336_REG_SHUTTER_M,
616:                          (uint8_t)(exposure >> 4) & 0xff);
617:   if (ret < 0)
618:     {
619:       return ret;
620:     }
621: 
622:   ret = sc2336_write_reg(priv, SC2336_REG_SHUTTER_L, val);
623:   if (ret < 0)
624:     {
625:       return ret;
626:     }
627: 
628:   priv->exposure = exposure;
629:   return OK;
630: }
631: 
632: /****************************************************************************
633:  * Name: sc2336_set_flip
634:  *
635:  * Description:
636:  *   Set the mirror / vertical flip bits.  0x3221 bits [2:1] control the
637:  *   horizontal mirror and bits [6:5] the vertical flip.
638:  *
639:  ****************************************************************************/
640: 
641: static int sc2336_set_flip(FAR struct sc2336_dev_s *priv, bool hflip,
642:                            bool vflip)
643: {
644:   uint8_t val;
645:   int ret;
646: 
647:   ret = sc2336_read_reg(priv, SC2336_REG_FLIP_MIRROR, &val);
648:   if (ret < 0)
649:     {
650:       return ret;
651:     }
652: 
653:   val &= ~(0x06 | 0x60);
654: 
655:   if (hflip)
656:     {
657:       val |= 0x06;
658:     }
659: 
660:   if (vflip)
661:     {
662:       val |= 0x60;
663:     }
664: 
665:   ret = sc2336_write_reg(priv, SC2336_REG_FLIP_MIRROR, val);
666:   if (ret < 0)
667:     {
668:       return ret;
669:     }
670: 
671:   priv->hflip = hflip;
672:   priv->vflip = vflip;
673:   return OK;
674: }
