687: /****************************************************************************
688:  * Name: sc2336_init
689:  ****************************************************************************/
690: 
691: static int sc2336_init(FAR struct imgsensor_s *sensor)
692: {
693:   FAR struct sc2336_dev_s *priv = (FAR struct sc2336_dev_s *)sensor;
694:   uint8_t pid_h;
695:   uint8_t pid_l;
696:   int ret;
697: 
698:   if (priv->i2c == NULL)
699:     {
700:       return -ENODEV;
701:     }
702: 
703:   /* The module has its own 24 MHz oscillator and the sensor reset is hard
704:    * pulled to 3.3 V, so there is no clock or reset line to sequence: only
705:    * the identification registers have to be read back.
706:    */
707: 
708:   ret = sc2336_read_reg(priv, SC2336_REG_SENSOR_ID_H, &pid_h);
709:   if (ret < 0)
710:     {
711:       _err("ERROR: SC2336: cannot read the sensor ID: %d\n", ret);
712:       priv->detected = false;
713:       return ret;
714:     }
715: 
716:   ret = sc2336_read_reg(priv, SC2336_REG_SENSOR_ID_L, &pid_l);
717:   if (ret < 0)
718:     {
719:       _err("ERROR: SC2336: cannot read the sensor ID: %d\n", ret);
720:       priv->detected = false;
721:       return ret;
722:     }
723: 
724:   if ((((uint16_t)pid_h << 8) | pid_l) != SC2336_PID)
725:     {
726:       _err("ERROR: SC2336: unexpected PID 0x%02x%02x (expected 0x%04x)\n",
727:            pid_h, pid_l, SC2336_PID);
728:       priv->detected = false;
729:       return -ENODEV;
730:     }
731: 
732:   priv->detected = true;
733:   return OK;
734: }
