/****************************************************************************
 * Name: sc2336_lock / sc2336_unlock
 *
 * Description:
 *   Serialise SCCB transactions and streaming-state changes.  Before
 *   sc2336_initialize() has created the mutex (lock_ready == false) the
 *   helpers are no-ops, which is safe because no other context can hold a
 *   reference to the sensor yet.
 *
 ****************************************************************************/

static void sc2336_lock(FAR struct sc2336_dev_s *priv)
{
  if (priv->lock_ready)
    {
      nxmutex_lock(&priv->lock);
    }
}

static void sc2336_unlock(FAR struct sc2336_dev_s *priv)
{
  if (priv->lock_ready)
    {
      nxmutex_unlock(&priv->lock);
    }
}

/****************************************************************************
 * Name: sc2336_write_table
 *
 * Description:
 *   Apply a register table in order.  The length is explicit: a 0xffff
 *   sentinel is deliberately NOT used, because a table that forgot it made
 *   this writer read past the end of its array and write the following
 *   .rodata words to the sensor over SCCB.
 *
 *   A 0xfffe entry delays for val milliseconds instead of writing.
 *
 ****************************************************************************/

static int sc2336_write_table(FAR struct sc2336_dev_s *priv,
                              FAR const struct sc2336_reg_s *table,
                              size_t nentries)
{
  size_t i;
  int ret;

  if (table == NULL || nentries == 0)
    {
      return -EINVAL;
    }

  for (i = 0; i < nentries; i++)
    {
      if (table[i].reg == SC2336_REG_DELAY)
        {
          nxsig_usleep((useconds_t)table[i].val * 1000);
          continue;
        }

      ret = sc2336_write_reg(priv, table[i].reg, table[i].val);
      if (ret < 0)
        {
          _err("ERROR: SC2336: table entry %u/%u write %04x=%02x failed: %d\n",
               (unsigned)i, (unsigned)nentries, table[i].reg, table[i].val,
               ret);
          return ret;
        }
    }

  return OK;
}

/****************************************************************************
 * Name: sc2336_verify_table
 *
 * Description:
 *   Read back a handful of registers the mode table is required to have
 *   programmed.  This is what distinguishes "the writes landed" from
 *   "streaming is on but the sensor never got configured", which look the
 *   same from the CSI side.
 *
 *   Mismatches are logged but do not abort the capture: register values can
 *   differ between sensor revisions, and refusing to stream on a diagnostic
 *   mismatch would turn a capture problem into a probe failure.  A failed
 *   SCCB read is also logged and tolerated for the same reason.
 *
 ****************************************************************************/

static int sc2336_verify_table(FAR struct sc2336_dev_s *priv)
{
  static const struct
  {
    uint16_t reg;
    uint8_t  want;
  } key[] =
  {
    {0x36e9, 0x53},   /* PLL locked */
    {0x37f9, 0x53},   /* PLL locked */
    {0x320c, 0x08},   /* HTS high */
    {0x320d, 0xca},   /* HTS low  -> 2250 */
    {0x320e, 0x04},   /* VTS high */
    {0x320f, 0xb0},   /* VTS low  -> 1200 */
    {0x4509, 0x38},   /* MIPI output settings */
    {0x0100, 0x00},   /* still in sleep */
  };

  unsigned int i;
  unsigned int checked = 0;
  unsigned int bad = 0;

  for (i = 0; i < sizeof(key) / sizeof(key[0]); i++)
    {
      uint8_t val = 0;
      int ret = sc2336_read_reg(priv, key[i].reg, &val);

      if (ret < 0)
        {
          _err("ERROR: SC2336: verify read %04x failed: %d\n",
               key[i].reg, ret);
          continue;
        }

      checked++;

      if (val != key[i].want)
        {
          bad++;
          _err("ERROR: SC2336: verify %04x = %02x, expected %02x\n",
               key[i].reg, val, key[i].want);
        }
    }

  _info("SC2336: register table verify: %u/%u match, %u mismatch\n",
        checked - bad, checked, bad);

  return bad == 0 ? OK : -EIO;
}

/****************************************************************************
 * Name: sc2336_set_stream
 *
 * Description:
 *   Enter or leave streaming (0x0100 = 1/0) and update the cached state.
 *
 ****************************************************************************/

static int sc2336_set_stream(FAR struct sc2336_dev_s *priv, bool on)
{
  int ret;

  ret = sc2336_write_reg(priv, SC2336_REG_SLEEP_MODE, on ? 0x01 : 0x00);
  if (ret < 0)
    {
      _err("ERROR: SC2336: failed to %s streaming: %d\n",
           on ? "start" : "stop", ret);
      return ret;
    }

  priv->streaming = on;
  return OK;
}
```

