CONFIG_DEBUG_VIDEO_ERROR=y
# CONFIG_DEBUG_VIDEO_WARN is not set
# CONFIG_DEBUG_VIDEO_INFO is not set
   * an ESP_RETURN_ON_ERROR, so a zero here means the DMA really is configured
   * against the bridge and the bridge really is enabled.  That is what
   * separates "capture never started" from "started but no data arrives from
   * the MIPI receive side", which is otherwise indistinguishable from the
   * outside (both show an armed channel and a static frame buffer).
   */

  _info("CSI: ctlr start rc=%d (%s)\n", (int)csi_start_err,
        csi_start_err == ESP_OK ? "DMA+bridge enabled" : "FAILED");

  if (csi_start_err != ESP_OK)
    {
      _err("ERROR: esp_cam_ctlr_start failed: %d\n", (int)csi_start_err);
      priv->callback = NULL;
      priv->cbarg    = NULL;
      return -EIO;
    }

#if ESP_CSI_CAPTURE_DIAG
  /* The sensor is still in sleep mode at this point (the SC2336 stream-on
   * happens later in the VIDIOC_S_FMT/REQBUFS chain), so defer the sampling
   * by 3 s to land inside the streaming window.
   */

  work_queue(LPWORK, &g_csi_diag_work, esp_csi_diag_series, NULL,
             MSEC2TICK(3000));
#endif

  priv->streaming = true;
  return OK;
}

/****************************************************************************
 * Name: esp_csi_data_stop_capture
 ****************************************************************************/

static int esp_csi_data_stop_capture(FAR struct imgdata_s *data)
{
  FAR struct esp_csi_priv_s *priv = (FAR struct esp_csi_priv_s *)data;

  if (!priv->streaming)
    {
      return OK;
    }

  if (esp_cam_ctlr_stop(priv->ctlr) != ESP_OK)
    {
      _err("ERROR: esp_cam_ctlr_stop failed\n");
    }

  priv->streaming = false;

  /* Report a frame that completed but has not been handed upwards yet, so
   * that the upper half does not wait forever for it.
   */

  if (priv->done_valid && priv->callback != NULL)
    {
      struct timeval ts = priv->done_ts;

      priv->done_valid = false;
      priv->done_buf   = NULL;
      priv->callback(0, priv->done_len, &ts, priv->cbarg);
      priv->nreported++;
    }

  priv->callback = NULL;
  priv->cbarg    = NULL;
  priv->next_buf = NULL;
  priv->next_len = 0;

"}]

