             BOARD_MIPI_PHY_LDO_CHAN, BOARD_MIPI_PHY_LDO_VOLTAGE_MV);
    }
  else
    {
      ret = esp_ldo_channel_release(&g_mipi_phy_ldo_config);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: failed to release MIPI PHY LDO: %d\n",
                 ret);
          return ret;
        }
    }

  return OK;
}

