s=s.replace('config->input_color         = CAM_CTLR_COLOR_RAW10;','config->input_color         = CAM_CTLR_COLOR_RAW8;',1)
s=s.replace('config->output_color        = CAM_CTLR_COLOR_RAW10;','config->output_color        = CAM_CTLR_COLOR_RAW8;',1)

# (2) defer controller creation to STREAMON
def_anchor='static int esp_csi_data_init(FAR struct imgdata_s *data)\n{'
d=s.index(def_anchor)
cstart=s.index('  memset(&csi_config, 0, sizeof(csi_config));', d)
mark='errout_ldo:'
lbl=s.index(mark, cstart)
cend=s.index('}\n', s.index('  return ret;\n', lbl))+2
block=s[cstart:cend]

s=s[:cstart]+'  return OK;\n}\n'+s[cend:]

body=block.replace('''  memset(&csi_config, 0, sizeof(csi_config));''',
'''  if (priv->ctlr_created)
    {
      return OK;
    }

  memset(&csi_config, 0, sizeof(csi_config));''')
