 * Name: esp_csi_data_uninit
 ****************************************************************************/'''
assert s.count(banner)==1
s=s.replace(banner,newfn+banner,1)

old='''  if (!priv->ctlr_created)
    {
      ret = esp_csi_data_init(data);
      if (ret < 0)
        {
          return ret;
        }
    }
'''
assert s.count(old)==1, s.count(old)
s=s.replace(old,'''  if (!priv->ctlr_created)
    {
      ret = esp_csi_ctlr_create(priv);
      if (ret < 0)
        {
          return ret;
        }
    }
''',1)

io.open(p,'w',encoding='utf-8').write(s)
print("ok: create=%d init=%d RAW8=%d" % (s.count('esp_csi_ctlr_create'), s.count('static int esp_csi_data_init'), s.count('CAM_CTLR_COLOR_RAW8')))
