            "metadata": {"source_tool": "dsh", "source_event": etype},
        }

        if etype in ("user/message", "assistant/message"):
            txt = text_of(data.get("message") or data)
            txt, n = redact(txt)
            redacted_total += n
            if txt:
                ev["text"] = txt
            m = (data.get("message") or {}).get("model")
            if m:
                ev["model"] = m

        elif etype == "tool/call":
            cid = data.get("callId")
            name = data.get("name")
            if not cid or not name:
                continue                      # role=tool 缺这两个字段不合法
            call_names[cid] = name
            ev["tool_name"] = name
            ev["tool_call_id"] = cid
            args = data.get("arguments")
            if isinstance(args, str):
                a, n = redact(args)
                redacted_total += n
                try:
                    args = json.loads(a)
                except Exception:
                    args = a
            ev["input"] = args

        elif etype == "tool/result":
            msg = data.get("message") or {}
            cid = ((msg.get("source") or {}).get("callId"))
            name = call_names.get(cid)
            if not cid or not name:
                continue                      # 找不到对应 call -> 不合法，跳过
            out = msg.get("content", data.get("output"))
            if isinstance(out, str):
                out, n = redact(out)
                redacted_total += n
            elif out is not None:
                txt, n = redact(json.dumps(out, ensure_ascii=False))
                redacted_total += n
                out = txt[:20000]
            ev["output"] = out
            ev["tool_name"] = name
            ev["tool_call_id"] = cid

        if redacted_total:
            ev["redacted_count"] = redacted_total

        events.append(ev)
        seq += 1

    return events


